export async function fetchSunlightData(e,t){let o=`https://api.open-meteo.com/v1/forecast?latitude=${e}&longitude=${t}&hourly=shortwave_radiation,weather_code&daily=sunrise,sunset&timezone=auto&past_days=1&forecast_days=3`,n=await fetch(o);if(!n.ok)throw Error("Failed to fetch data from Open-Meteo API");return await n.json()}export function processDataForDaytime(e){let t=e.timezone||"UTC",o=new Date().toLocaleString("en-US",{timeZone:t,hour12:!1}),n=new Date(o),a=e.daily.sunrise.map(e=>new Date(e)),r=e.daily.sunset.map(e=>new Date(e)),i,u;for(let l=0;l<a.length;l++)if(n<=r[l]){i=a[l],u=r[l];break}i||(i=a[a.length-1],u=r[r.length-1]);let s=new Date(i);s.setMinutes(0,0,0);let h=new Date(u);h.setHours(h.getHours()+1),h.setMinutes(0,0,0);let c=[],d=[],w=[];return e.hourly.time.forEach((t,o)=>{let n=new Date(t);if(n>=s&&n<=h){let a=n.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),r=e.hourly.weather_code?e.hourly.weather_code[o]:null,i=getWeatherIcon(r);c.push(a),d.push(i),w.push(e.hourly.shortwave_radiation[o])}}),{labels:c,values:w,weatherIcons:d,date:i.toLocaleDateString()}}function getWeatherIcon(e){return null==e?"":0===e?"☀️":1===e||2===e?"\uD83C\uDF24️":3===e?"☁️":45===e||48===e?"\uD83C\uDF2B️":e>=51&&e<=67?"\uD83C\uDF27️":e>=71&&e<=77?"❄️":e>=80&&e<=82?"\uD83C\uDF26️":85===e||86===e?"\uD83C\uDF28️":e>=95&&e<=99?"⛈️":""}